package io.github.arkivx0.lanternly

import io.github.arkivx0.lanternly.core.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.util.UUID

/** Same vectors as the Windows tests (spec/test_vectors.json and spec/keyfile_vector.json, generated by independent Python reference code). */
class ProtocolTest {
    private val v = JSONObject(javaClass.classLoader!!.getResourceAsStream("test_vectors.json")!!.bufferedReader().readText())
    private fun hex(b: ByteArray) = b.joinToString("") { "%02x".format(it) }
    private fun unhex(s: String) = ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }

    @Test fun ble() {
        assertEquals(v.getString("ble_key_encrypt").substring(0, 16), hex(Ble.pairRequest("AABBCCDDEEFF", "12345678", byteArrayOf(1, 2, 3, 4, 5, 6, 7, 8)).copyOfRange(9, 17)))
        val sk = Ble.sessionKey("AABBCCDDEEFF", "12345678", byteArrayOf(1, 2, 3, 4, 5, 6, 7, 8), byteArrayOf(0x0d, 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27))
        assertEquals(v.getString("ble_sk"), hex(sk))
        val mac = Ble.macLe("AA:BB:CC:DD:EE:FF")
        assertEquals(v.getString("ble_enc"), hex(Ble.command(sk, mac, 0x1234, 5, Ble.CMD_BRIGHTNESS, Ble.brightnessData(60))))
        assertEquals(v.getString("ble_dec_of_enc"), hex(Ble.decryptNotify(sk, mac, unhex(v.getString("ble_enc")))))
        assertThrows(SecurityException::class.java) { Ble.sessionKey("a", "b", ByteArray(8), ByteArray(9) { 0x0e }) }
    }

    @Test fun caps() { assertTrue(Caps.count > 100); assertTrue(Caps.forType(6) and Caps.COLOR != 0); assertEquals(Caps.ON_OFF or Caps.DIM, Caps.forType(99999)) }

    @Test fun vaultRoundTripAndOldCloudFieldsAreDropped() {
        val v1 = Vault(listOf(Home(7, "H", "M", "P", listOf(Room(1, "R", listOf(2))), mutableListOf(Bulb("B", 2, 6, "AA:BB:CC:DD:EE:01")))))
        val v2 = Vault.fromJson(v1.toJson())
        assertEquals("P", v2.homes[0].meshPassword); assertEquals(2, v2.homes[0].rooms[0].meshIds[0])
        val old = Vault.fromJson("""{"Format":1,"Homes":[{"Id":1,"MeshName":"m","MeshPassword":"p","Bulbs":[{"Name":"x","DeviceId":5,"MeshId":2}]}],"Cloud":{"AccessToken":"secret"}}""")
        assertEquals("p", old.homes[0].meshPassword); assertFalse(old.toJson().contains("secret"))
    }

    @Test fun keyFileReadsReferenceVector() {
        val kv = JSONObject(javaClass.classLoader!!.getResourceAsStream("keyfile_vector.json")!!.bufferedReader().readText())
        assertEquals(kv.getString("mesh_password"), KeyFile.import(kv.getString("file"), kv.getString("passphrase")).homes[0].meshPassword)
    }

    @Test fun keyFileRoundTrip() {
        val v = Vault(listOf(home()))
        val prot = KeyFile.export(v, "correct horse")
        assertTrue(KeyFile.isProtected(prot)); assertFalse(prot.contains("123456"))
        assertEquals("123456", KeyFile.import(prot, "correct horse").homes[0].meshPassword)
        assertThrows(KeyFile.WrongPassphrase::class.java) { KeyFile.import(prot, "wrong") }
        assertThrows(KeyFile.WrongPassphrase::class.java) { KeyFile.import(prot, null) }
        assertEquals("123456", KeyFile.import(KeyFile.export(v, null), null).homes[0].meshPassword)
    }

    /** Factory reset = Telink kick-out, as the official app's KickOutDeviceCommand: E3 11 02 01. */
    @Test fun kickOutCommandLayout() {
        assertEquals(0xe3, Ble.CMD_KICK_OUT); assertArrayEquals(byteArrayOf(1), Ble.kickOutData())
        val sk = ByteArray(16) { (it + 1).toByte() }; val mac = Ble.macLe("AA:BB:CC:DD:EE:FF")
        val plain = unhex("341200000007" + "00e3110201" + "000000000000000000")
        assertArrayEquals(Ble.encryptPacket(sk, mac, plain), Ble.command(sk, mac, 0x1234, 7, Ble.CMD_KICK_OUT, Ble.kickOutData()))
    }

    /** Reset bulb end to end: node returns to telink_mesh1/123, the app forgets it (home and rooms), and it can be adopted again. */
    @Test fun resetBulbEndToEnd() {
        val h = home(); h.rooms = listOf(Room(9, "R", listOf(h.bulbs[0].meshId, h.bulbs[1].meshId)))
        val target = h.bulbs[0]; val node = FakeNode(target.mac, h.meshName, h.meshPassword)
        val s = BleSession(node, h); s.login()
        BulbReset.send(Router(listOf(s)), h, target)
        assertTrue(h.bulbs.contains(target)) // not forgotten until confirmed
        BulbReset.forget(h, target)
        assertEquals("e3110201000000000000", hex(node.plain[0].copyOfRange(7, 17)))
        assertEquals(target.meshId, (node.plain[0][5].toInt() and 0xff) or ((node.plain[0][6].toInt() and 0xff) shl 8))
        assertTrue(node.kicked >= 1); assertFalse(h.bulbs.contains(target)); assertFalse(target.meshId in h.rooms[0].meshIds)
        assertThrows(SecurityException::class.java) { BleSession(node, home()).login() }
        val (n, p) = Ble.newMeshCredentials(); BleSession.provision(node, n, p)
        val fresh = Home(2, "F", n, p, emptyList(), mutableListOf(Bulb("Again", 0, Caps.ALL_CONTROLS, node.mac)))
        val s2 = BleSession(node, fresh); s2.login()
        assertEquals(Via.BLE, Router(listOf(s2)).send(fresh, fresh.bulbs[0], Cmd.Power(true)))
        // not sent: nothing removed
        val h2 = home(); val b2 = h2.bulbs[0]
        assertThrows(Exception::class.java) { BulbReset.send(Router(emptyList()), h2, b2) }
        assertTrue(h2.bulbs.contains(b2))
    }

    /** R2: never reset a group/broadcast/unknown address, or one shared by two bulbs; nothing is sent. */
    @Test fun resetRefusesBadOrSharedAddress() {
        for (a in listOf(0, 0x8000, 0xFFFF)) {
            val h = home(); h.bulbs[0].meshId = a
            val node = FakeNode(h.bulbs[1].mac, h.meshName, h.meshPassword); val s = BleSession(node, h); s.login()
            assertNotNull(BulbReset.refuseReason(h, h.bulbs[0]))
            assertThrows(IllegalArgumentException::class.java) { BulbReset.send(Router(listOf(s)), h, h.bulbs[0]) }
            assertEquals(0, node.kicked); assertTrue(node.plain.none { it.size > 7 && (it[7].toInt() and 0xff) == Ble.CMD_KICK_OUT })
        }
        val h = home(); h.bulbs[1].meshId = h.bulbs[0].meshId
        assertNotNull(BulbReset.refuseReason(h, h.bulbs[0]))
        assertThrows(IllegalArgumentException::class.java) { BulbReset.send(Router(emptyList()), h, h.bulbs[0]) }
        assertNull(BulbReset.refuseReason(home(), home().bulbs[0])); assertTrue(BulbReset.validAddress(0x7FFF))
    }

    /** R1: the bulb's own schedules go with it (same home, exact target); others stay. */
    @Test fun resetDeletesOnlyThatBulbsSchedules() {
        val h = home(); val b = h.bulbs[0]
        val mine = Schedule(1, true, 7, 0, 127, "on", h.id, "bulb:${b.meshId}")
        val l = listOf(mine, Schedule(2, true, 7, 0, 127, "on", h.id, "bulb:3"), Schedule(3, true, 7, 0, 127, "on", h.id, "room:1"),
            Schedule(4, true, 7, 0, 127, "on", h.id, "all"), Schedule(5, true, 7, 0, 127, "on", 999, "bulb:${b.meshId}"), Schedule(6, true, 7, 0, 127, "on", h.id, "bulb:${b.meshId}0"))
        assertEquals(listOf(mine), BulbReset.schedulesFor(h, b, l))
        // a later bulb with the same address is not targeted by what is left
        BulbReset.forget(h, b); val left = l - BulbReset.schedulesFor(h, b, l).toSet()
        h.bulbs.add(Bulb("New", b.meshId, 6, "AA:BB:CC:DD:EE:09"))
        assertTrue(left.filter { it.homeId == h.id && it.target.startsWith("bulb:") }.none { Schedules.targets(h, it).any { x -> x.name == "New" } })
    }

    /** R3: confirmed only when the bulb's own MAC advertises telink_mesh1. */
    @Test fun resetConfirmedOnlyByOwnFactoryAdvert() {
        val b = home().bulbs[0]
        assertTrue(BulbReset.confirmed(b, listOf("AA:BB:CC:DD:EE:07", "aa:bb:cc:dd:ee:01")))
        assertFalse(BulbReset.confirmed(b, listOf("AA:BB:CC:DD:EE:02"))); assertFalse(BulbReset.confirmed(b, emptyList()))
        assertFalse(BulbReset.confirmed(Bulb("x", 2, 6, ""), listOf("")))
    }

    /** Key-file import rejects group/broadcast addresses and duplicates; 0 (unknown) is allowed. */
    @Test fun importValidatesAddresses() {
        fun file(vararg ids: Int, room: Int = 2) = Vault(listOf(Home(1, "H", "n", "p", listOf(Room(1, "R", listOf(room))),
            ids.mapIndexed { i, m -> Bulb("B$i", m, 6, "AA:BB:CC:DD:EE:0$i") }.toMutableList()))).toJson()
        assertEquals(2, KeyFile.import(file(2, 3), null).homes[0].bulbs.size)
        assertEquals(2, KeyFile.import(file(0, 0), null).homes[0].bulbs.size)
        for (bad in listOf(file(2, 0xFFFF), file(2, 0x8000), file(2, -1), file(2, 2), file(2, 3, room = 0xFFFF)))
            assertThrows(IllegalArgumentException::class.java) { KeyFile.import(bad, null) }
        assertThrows(IllegalArgumentException::class.java) { KeyFile.import(KeyFile.export(Vault.fromJson(file(5, 0xFFFF)), "pw"), "pw") }
    }

    /** Identify / blink, as in the official app: F7 11 02 03 01 (start) / 03 02 (stop). */
    @Test fun identifyCommandLayout() {
        assertEquals(0xf7, Ble.CMD_IDENTIFY)
        assertArrayEquals(byteArrayOf(3, 1), Ble.identifyData(true)); assertArrayEquals(byteArrayOf(3, 2), Ble.identifyData(false))
        val sk = ByteArray(16) { it.toByte() }; val mac = Ble.macLe("AA:BB:CC:DD:EE:FF")
        for ((start, last) in listOf(true to 1, false to 2)) {
            val plain = unhex("341200000005 00f7110203".replace(" ", "") + "%02x".format(last) + "0000000000000000")
            assertArrayEquals(Ble.encryptPacket(sk, mac, plain), Ble.command(sk, mac, 0x1234, 5, Ble.CMD_IDENTIFY, Ble.identifyData(start)))
        }
    }

    @Test fun redScene() {
        val red = Scenes.all.first { it.name == "Red" }
        assertEquals(listOf(Cmd.Power(true), Cmd.Brightness(100), Cmd.Rgb(255, 0, 0)), red.steps)
        val w = Scenes.stepsFor(red, Bulb("W", 2, 99999, "AA:BB:CC:DD:EE:03"))
        assertEquals(Cmd.Power(true), w.first()); assertTrue(w.none { it is Cmd.Rgb })
        assertEquals(listOf(Cmd.Power(true), Cmd.Brightness(100), Cmd.Rgb(255, 0, 0)), Scenes.stepsFor(red, Bulb("C", 2, 6, "AA:BB:CC:DD:EE:04")))
    }

    @Test fun colorTempZeroIsClampedToOne() = assertEquals(1, Ble.colorTempData(0)[1].toInt())

    @Test fun batchAndSceneReportPartialSuccess() {
        val h = home()
        val flaky = object : Link {
            override val kind = Via.BLE; override var onState: ((Home?, BulbState) -> Unit)? = null
            override fun canReach(h: Home, b: Bulb) = true
            override fun send(h: Home, b: Bulb, c: Cmd) { if (b.name == "Desk") throw java.io.IOException("radio busy") }
        }
        val r = Router(listOf(flaky))
        assertEquals("1/2 bulbs updated (Desk: radio busy)", r.sendMany(h, h.bulbs, Cmd.Power(true)).toString())
        val sc = Scenes.apply(r, h, Scenes.all[0]); assertEquals(1, sc.ok); assertFalse(sc.allOk)
        assertThrows(NotReachable::class.java) { Router(emptyList()).send(h, h.bulbs[0], Cmd.Power(true)) }
    }

    // ---- end to end with fakes ----
    private fun home() = Home(50, "T", "AABBCCDDEEFF", "123456", listOf(Room(1, "Office", listOf(2, 3))),
        mutableListOf(Bulb("Lamp", 2, 6, "AA:BB:CC:DD:EE:01"), Bulb("Desk", 3, 6, "AA:BB:CC:DD:EE:02")))

    @Test fun factoryPairingWriteMatchesPublishedConstant() =
        assertEquals("0ca0a1a2a3a4a5a6a78db674711b855a79", hex(Ble.pairRequest("telink_mesh1", "123", ByteArray(8) { (0xa0 + it).toByte() })))

    @Test fun adoptResetBulb() {
        val node = FakeNode("AA:BB:CC:DD:EE:09", Ble.FACTORY_NAME, Ble.FACTORY_PASSWORD)
        val (n, p) = Ble.newMeshCredentials()
        BleSession.provision(node, n, p)
        val h = Home(1, "Mine", n, p, emptyList(), mutableListOf(Bulb("Red lamp", 0, Caps.ALL_CONTROLS, node.mac)))
        val s = BleSession(node, h); s.login()
        assertEquals(Via.BLE, Router(listOf(s)).send(h, h.bulbs[0], Cmd.Power(true)))
        assertTrue(h.bulbs[0].has(Caps.COLOR))
    }

    private class FakeNode(override val mac: String, var name: String, var pass: String) : GattPort {
        var newName: ByteArray? = null; var newPass: ByteArray? = null; var kicked = 0
        private fun dec(x: ByteArray): ByteArray {
            val c = javax.crypto.Cipher.getInstance("AES/ECB/NoPadding"); c.init(javax.crypto.Cipher.DECRYPT_MODE, javax.crypto.spec.SecretKeySpec(sk!!.reversedArray(), "AES"))
            return c.doFinal(x.copyOfRange(1, 17).reversedArray()).reversedArray()
        }
        var sk: ByteArray? = null; var reply = ByteArray(0); val plain = ArrayList<ByteArray>()
        override fun write(ch: UUID, data: ByteArray, withResponse: Boolean) {
            if (ch == Ble.PAIR && data[0].toInt() in 4..6) {
                when (data[0].toInt()) { 4 -> newName = dec(data); 5 -> newPass = dec(data)
                    else -> { name = String(newName!!).trimEnd('\u0000'); pass = String(newPass!!).trimEnd('\u0000'); reply = byteArrayOf(7) } }
            } else if (ch == Ble.PAIR) {
                val r = data.copyOfRange(1, 9)
                reply = if (Ble.pairRequest(name, pass, r).contentEquals(data)) byteArrayOf(0x0d, 9, 8, 7, 6, 5, 4, 3, 2) + ByteArray(8) else ByteArray(17) { 0x0e }
                if (reply[0] == 0x0d.toByte()) sk = Ble.sessionKey(name, pass, r, reply)
            } else if (ch == Ble.COMMAND) {
                val m = Ble.macLe(mac); val p = data.copyOf()
                val ks = Ble.aes(sk!!, byteArrayOf(0, m[0], m[1], m[2], m[3], 1, p[0], p[1], p[2], 0, 0, 0, 0, 0, 0, 0))
                for (i in 0 until 15) p[i + 5] = (p[i + 5].toInt() xor ks[i].toInt()).toByte()
                val chk = Ble.encryptPacket(sk!!, m, p.copyOf().also { it[3] = 0; it[4] = 0 })
                assertArrayEquals(data.copyOfRange(3, 5), chk.copyOfRange(3, 5))
                plain += p
                if (p[7].toInt() and 0xff == Ble.CMD_KICK_OUT && p[10].toInt() == Ble.KICK_OUT_FACTORY_RESET) { name = Ble.FACTORY_NAME; pass = Ble.FACTORY_PASSWORD; kicked++ }
            }
        }
        override fun read(ch: UUID) = reply
        override fun subscribe(ch: UUID, onNotify: (ByteArray) -> Unit) {}
        override fun close() {}
    }

    @Test fun bleSessionEndToEnd() {
        val h = home(); val node = FakeNode(h.bulbs[0].mac, h.meshName, h.meshPassword)
        val s = BleSession(node, h); s.login()
        assertEquals(Via.BLE, Router(listOf(s)).send(h, h.bulbs[1], Cmd.Rgb(1, 2, 3)))
        val p = node.plain.single()
        assertEquals(3, p[5].toInt()); assertEquals(Ble.CMD_COLOR, p[7].toInt() and 0xff)
        assertArrayEquals(byteArrayOf(4, 1, 2, 3), p.copyOfRange(10, 14))
        Router(listOf(s)).send(h, h.bulbs[1], Cmd.Identify(true)); Router(listOf(s)).send(h, h.bulbs[1], Cmd.Identify(false))
        assertEquals("f7110203010000000000", hex(node.plain[1].copyOfRange(7, 17)))
        assertEquals("f7110203020000000000", hex(node.plain[2].copyOfRange(7, 17)))
        val bad = BleSession(FakeNode(h.bulbs[0].mac, h.meshName, "nope"), h)
        assertThrows(SecurityException::class.java) { bad.login() }
    }
}
